// GENERATED by worker/bundle.mjs from lib.js and index.js: change those, not this file.
// Pure rules of the crowd data service (no Cloudflare calls), so Node can test them offline.
// What a Worker may accept, and how reports become published figures. See docs/CROWD.md.

const MIN_REPORTERS = 5;       // distinct accounts needed before a figure is published
const BAND = 3;                // a value more than 3x above or below the median is held back
const REGIONS = ['US', 'PAL'];
const CONDITIONS = ['sealed', 'complete', 'loose'];
const CURRENCIES = ['USD', 'GBP', 'EUR'];
const MAX_GAMES_PER_ACCOUNT = 600;
const MAX_COPIES = 99;
const MAX_LIST = 2000;         // entries of the account's own saved list (title, region, condition, count)
const MAX_REPORTS_PER_DAY = 20;
const MAX_PRICE = 20000;       // in the report's own currency
const MONTHS_BACK = 24;

// The dashboard sends priceKey(): lower case words and digits, one space between.
function cleanGame(value) {
    const text = String(value ?? '').trim();
    return /^[a-z0-9]+(?: [a-z0-9]+)*$/.test(text) && text.length >= 2 && text.length <= 100 ? text : null;
}

const whole = (n) => Number.isInteger(n) && n >= 0 && n <= MAX_COPIES;

function cleanCopies(body) {
    const game = cleanGame(body?.game);
    const { sealed, complete, loose } = body ?? {};
    if (!game || ![sealed, complete, loose].every(whole)) return null;
    return { game, sealed, complete, loose };
}

// The account's own list, kept so a new browser can load it back. Private to the account: never published, never read by stats.
// No price, name or address: a title (as the dashboard spells it), a region, a condition and how many.
function cleanList(list) {
    if (!Array.isArray(list) || list.length > MAX_LIST) return null;
    const out = [];
    for (const item of list) {
        const title = typeof item?.title === 'string' ? item.title.trim() : '';
        const qty = item?.qty;
        // eslint-disable-next-line no-control-regex
        if (!title || title.length > 100 || /[\u0000-\u001f\u007f<>]/.test(title)) return null;
        if (!REGIONS.includes(item.region) || !CONDITIONS.includes(item.condition) || !Number.isInteger(qty) || qty < 1 || qty > MAX_COPIES) return null;
        out.push({ title, region: item.region, condition: item.condition, qty });
    }
    return out;
}

// months: "2026-10". Not in the future, not older than MONTHS_BACK.
function cleanMonth(value, now = new Date()) {
    if (!/^\d{4}-(0[1-9]|1[0-2])$/.test(String(value))) return null;
    const [y, m] = value.split('-').map(Number);
    const index = y * 12 + (m - 1);
    const current = now.getUTCFullYear() * 12 + now.getUTCMonth();
    return index <= current && index >= current - MONTHS_BACK ? value : null;
}

function cleanReport(body, now = new Date()) {
    const game = cleanGame(body?.game);
    const price = typeof body?.price === 'number' ? Math.round(body.price * 100) / 100 : NaN;
    const month = cleanMonth(body?.month, now);
    if (!game || !month || !Number.isFinite(price) || price <= 0 || price > MAX_PRICE) return null;
    if (!REGIONS.includes(body.region) || !CONDITIONS.includes(body.condition)
        || !CURRENCIES.includes(body.currency)) return null;
    return { game, region: body.region, condition: body.condition, currency: body.currency, price, month };
}

function median(values) {
    const sorted = [...values].sort((a, b) => a - b);
    const mid = sorted.length >> 1;
    return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

// rows: [{ account, price }] for ONE game, region, condition and currency.
// One account counts once (the median of what it reported), so nobody outweighs the rest by sending many.
// Under MIN_REPORTERS accounts nothing is published. A figure far from the middle is held back, not deleted:
// every call looks at all the rows again, so it counts as soon as the crowd agrees with it.
function summarise(rows) {
    const byAccount = new Map();
    for (const { account, price } of rows) {
        if (!byAccount.has(account)) byAccount.set(account, []);
        byAccount.get(account).push(price);
    }
    const values = [...byAccount.values()].map(median);
    if (values.length < MIN_REPORTERS) return { published: false, reporters: values.length };
    const middle = median(values);
    const kept = values.filter(v => v <= middle * BAND && v >= middle / BAND);
    if (kept.length < MIN_REPORTERS) return { published: false, reporters: values.length, held: values.length - kept.length };
    return { published: true, reporters: kept.length, held: values.length - kept.length,
        median: Math.round(median(kept) * 100) / 100, low: Math.min(...kept), high: Math.max(...kept) };
}

// rows: [{ account, sealed, complete, loose }] for one game. Counts are published only for MIN_REPORTERS owners or more.
function summariseOwners(rows) {
    const owners = rows.filter(r => r.sealed + r.complete + r.loose > 0);
    if (owners.length < MIN_REPORTERS) return { published: false };
    const sum = (key) => owners.reduce((total, r) => total + r[key], 0);
    return { published: true, owners: owners.length, sealed: sum('sealed'), complete: sum('complete'), loose: sum('loose') };
}

async function sha256Hex(text) {
    const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
    return [...new Uint8Array(bytes)].map(b => b.toString(16).padStart(2, '0')).join('');
}

function randomToken(bytes) {
    const raw = crypto.getRandomValues(new Uint8Array(bytes));
    return [...raw].map(b => b.toString(16).padStart(2, '0')).join('');
}

// Cloudflare Worker for the dashboard's opt-in crowd data (docs/CROWD.md).
// Anonymous accounts, collection counts, purchase reports, and published figures only when enough people agree.
// Keeps no email, no address and no name. Nothing here reads or writes the repository.

const DAY = 86400000;
const today = () => Math.floor(Date.now() / DAY);
const MAX_BODY = 400_000;
const REGISTER_PER_DAY = 5;           // per hashed network address, rotating daily
const COLLECTION_SAVES_PER_DAY = 30;  // per account

function corsHeaders(request, env) {
    const allowed = String(env.ALLOW_ORIGIN || '').split(',').map(s => s.trim()).filter(Boolean);
    const origin = request.headers.get('Origin');
    const headers = { 'Vary': 'Origin' };
    if (origin && allowed.includes(origin)) {
        headers['Access-Control-Allow-Origin'] = origin;
        headers['Access-Control-Allow-Methods'] = 'GET, POST, PUT, DELETE, OPTIONS';
        headers['Access-Control-Allow-Headers'] = 'Authorization, Content-Type';
        headers['Access-Control-Max-Age'] = '86400';
    }
    return headers;
}

function reply(request, env, status, body, extra = {}) {
    return new Response(body === null ? null : JSON.stringify(body), {
        status, headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-store', ...corsHeaders(request, env), ...extra },
    });
}

async function readJson(request) {
    const text = await request.text();
    if (text.length > MAX_BODY) return null;
    try { return JSON.parse(text); } catch { return null; }
}

// "Authorization: Bearer <id>.<key>": the account id and its secret key. Only the key's hash is stored.
async function authenticate(request, env) {
    const header = request.headers.get('Authorization') || '';
    const match = header.match(/^Bearer ([0-9a-f]{32})\.([0-9a-f]{64})$/);
    if (!match) return null;
    const row = await env.DB.prepare('SELECT key_hash FROM accounts WHERE id = ?').bind(match[1]).first();
    if (!row) return null;
    const hash = await sha256Hex(match[2]);
    return hash === row.key_hash ? match[1] : null;
}

// Counts something against a bucket for today; false when the limit is reached.
async function allow(env, bucket, limit) {
    const day = today();
    await env.DB.prepare('INSERT INTO limits (bucket, day, n) VALUES (?, ?, 1) ON CONFLICT(bucket, day) DO UPDATE SET n = n + 1')
        .bind(bucket, day).run();
    const row = await env.DB.prepare('SELECT n FROM limits WHERE bucket = ? AND day = ?').bind(bucket, day).first();
    return row.n <= limit;
}

async function register(request, env) {
    if (!env.SALT) return reply(request, env, 503, { error: 'not configured' });
    const address = request.headers.get('CF-Connecting-IP') || 'unknown';
    const bucket = 'reg:' + await sha256Hex(`${env.SALT}|${today()}|${address}`);
    if (!await allow(env, bucket, REGISTER_PER_DAY)) return reply(request, env, 429, { error: 'too many accounts from here today' });
    const id = randomToken(16), key = randomToken(32);
    await env.DB.prepare('INSERT INTO accounts (id, key_hash, created) VALUES (?, ?, ?)').bind(id, await sha256Hex(key), today()).run();
    return reply(request, env, 201, { id, key });   // shown once: the server keeps only the key's hash
}

async function saveCollection(request, env, account) {
    const body = await readJson(request);
    if (!body || !Array.isArray(body.items) || body.items.length > MAX_GAMES_PER_ACCOUNT) return reply(request, env, 400, { error: 'bad collection' });
    const items = body.items.map(cleanCopies);
    if (items.some(item => !item)) return reply(request, env, 400, { error: 'bad collection' });
    const list = body.list === undefined ? undefined : cleanList(body.list);
    if (list === null) return reply(request, env, 400, { error: 'bad collection' });
    if (!await allow(env, 'col:' + account, COLLECTION_SAVES_PER_DAY)) return reply(request, env, 429, { error: 'too many saves today' });
    // The saved list replaces the old one, so a game taken out of the collection disappears here too.
    const day = today();
    const statements = [env.DB.prepare('DELETE FROM copies WHERE account = ?').bind(account)];
    for (const { game, sealed, complete, loose } of items) {
        if (sealed + complete + loose === 0) continue;
        statements.push(env.DB.prepare('INSERT OR REPLACE INTO copies (account, game, sealed, complete, loose, updated) VALUES (?, ?, ?, ?, ?, ?)')
            .bind(account, game, sealed, complete, loose, day));
    }
    await env.DB.batch(statements);
    // The list itself (so a new browser can load it back) is a separate step: an older database without the table still gets its counts.
    let listSaved = false;
    if (list !== undefined) {
        try {
            await env.DB.prepare('INSERT OR REPLACE INTO lists (account, data, updated) VALUES (?, ?, ?)').bind(account, JSON.stringify(list), day).run();
            listSaved = true;
        } catch { /* no lists table yet */ }
    }
    return reply(request, env, 200, { saved: statements.length - 1, list: listSaved });
}

// The signed-in account's own saved list; null when none was saved (or the table is not there yet).
async function getCollection(request, env, account) {
    if (!await allow(env, 'get:' + account, 60)) return reply(request, env, 429, { error: 'too many today' });
    let list = null;
    try {
        const row = await env.DB.prepare('SELECT data FROM lists WHERE account = ?').bind(account).first();
        if (row) list = cleanList(JSON.parse(row.data));
    } catch { /* no lists table yet, or nothing saved */ }
    return reply(request, env, 200, { list });
}

async function addReport(request, env, account) {
    const report = cleanReport(await readJson(request));
    if (!report) return reply(request, env, 400, { error: 'bad report' });
    const day = today();
    const count = await env.DB.prepare('SELECT COUNT(*) AS n FROM reports WHERE account = ? AND created = ?').bind(account, day).first();
    if (count.n >= MAX_REPORTS_PER_DAY) return reply(request, env, 429, { error: 'too many reports today' });
    await env.DB.prepare('INSERT INTO reports (account, game, region, condition, currency, price, month, source, created) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)')
        .bind(account, report.game, report.region, report.condition, report.currency, report.price, report.month, 'other', day).run();
    return reply(request, env, 201, { ok: true });
}

async function deleteAccount(request, env, account) {
    await env.DB.batch([
        env.DB.prepare('DELETE FROM copies WHERE account = ?').bind(account),
        env.DB.prepare('DELETE FROM reports WHERE account = ?').bind(account),
        env.DB.prepare('DELETE FROM limits WHERE bucket = ?').bind('col:' + account),
        env.DB.prepare('DELETE FROM accounts WHERE id = ?').bind(account),
    ]);
    try { await env.DB.prepare('DELETE FROM lists WHERE account = ?').bind(account).run(); } catch { /* no lists table */ }
    try { await env.DB.prepare('DELETE FROM limits WHERE bucket = ?').bind('get:' + account).run(); } catch { /* nothing to remove */ }
    return reply(request, env, 200, { deleted: true });
}

// Figures anyone may read: only groups with enough accounts, and never one account's rows.
async function stats(request, env) {
    const cache = caches.default;
    const cacheKey = new Request(new URL('/api/stats', request.url).toString());
    let response = await cache.match(cacheKey);
    if (!response) {
        const reports = (await env.DB.prepare('SELECT game, region, condition, currency, account, price FROM reports').all()).results;
        const copies = (await env.DB.prepare('SELECT game, account, sealed, complete, loose FROM copies').all()).results;
        const groups = new Map();
        for (const r of reports) {
            const key = `${r.game}|${r.region}|${r.condition}|${r.currency}`;
            if (!groups.has(key)) groups.set(key, []);
            groups.get(key).push({ account: r.account, price: r.price });
        }
        const prices = {};
        for (const [key, rows] of groups) {
            const [game, region, condition, currency] = key.split('|');
            const figure = summarise(rows);
            if (!figure.published) continue;
            (prices[game] ||= []).push({ region, condition, currency, median: figure.median, low: figure.low, high: figure.high, reporters: figure.reporters });
        }
        const byGame = new Map();
        for (const c of copies) {
            if (!byGame.has(c.game)) byGame.set(c.game, []);
            byGame.get(c.game).push(c);
        }
        const owners = {};
        for (const [game, rows] of byGame) {
            const figure = summariseOwners(rows);
            if (figure.published) owners[game] = { owners: figure.owners, sealed: figure.sealed, complete: figure.complete, loose: figure.loose };
        }
        response = new Response(JSON.stringify({ generated: new Date().toISOString(), prices, owners }), {
            headers: { 'Content-Type': 'application/json', 'Cache-Control': 'public, max-age=300' },
        });
        await cache.put(cacheKey, response.clone());
    }
    const headers = new Headers(response.headers);
    for (const [name, value] of Object.entries(corsHeaders(request, env))) headers.set(name, value);
    return new Response(response.body, { status: 200, headers });
}

export default {
    async fetch(request, env) {
        const { pathname } = new URL(request.url);
        if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: corsHeaders(request, env) });
        try {
            if (request.method === 'GET' && pathname === '/api/stats') return await stats(request, env);
            if (request.method === 'POST' && pathname === '/api/register') return await register(request, env);
            const routes = { 'GET /api/collection': getCollection, 'PUT /api/collection': saveCollection, 'POST /api/report': addReport, 'DELETE /api/account': deleteAccount };
            const handler = routes[`${request.method} ${pathname}`];
            if (!handler) return reply(request, env, 404, { error: 'not found' });
            const account = await authenticate(request, env);
            if (!account) return reply(request, env, 401, { error: 'sign in again' });
            return await handler(request, env, account);
        } catch {
            return reply(request, env, 500, { error: 'something went wrong' });   // never echo an error: it could hold what was sent
        }
    },
};
